() => {
  const videos = [...document.querySelectorAll('video')].map(v => ({
    src: v.currentSrc || v.src,
    duration: v.duration,
    poster: v.poster
  }));
  const imgs = [...document.querySelectorAll('img')].map(img => ({
    src: img.src,
    alt: img.alt,
    w: img.naturalWidth,
    h: img.naturalHeight
  })).filter(i => i.src && !i.src.startsWith('data:'));
  const text = document.body.innerText.slice(0, 8000);
  return { videos, imgs: imgs.slice(0, 30), textSnippet: text };
}

async () => {
  const v = document.querySelector('video');
  if (!v) return { error: 'no video' };
  v.pause();
  const times = [0.5, 3, 6, 9, 12, 15, 18, 21, 24, 27, 30];
  const seek = (t) => new Promise((resolve) => {
    const done = () => { v.removeEventListener('seeked', done); resolve(t); };
    v.addEventListener('seeked', done);
    v.currentTime = t;
  });
  await seek(0.5);
  return { duration: v.duration, current: v.currentTime, w: v.videoWidth, h: v.videoHeight };
}

