        let cg = try gen.copyCGImage(at: cm, actualTime: nil)
        let rep = NSBitmapImageRep(cgImage: cg)
        guard let data = rep.representation(using: .jpeg, properties: [.compressionFactor: 0.7]) else {
            fputs("no data at \(t)\n", stderr)
            continue
        }
        let path = "\(outDir)/f-\(Int(t)).jpg"
        try data.write(to: URL(fileURLWithPath: path))
        fputs("wrote \(path) \(cg.width)x\(cg.height)\n", stderr)
